package com.example.jwtlogin.controllers;
import com.example.jwtlogin.model.*; import com.example.jwtlogin.repository.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.http.ResponseEntity; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.time.LocalDateTime; import java.util.List;
@CrossOrigin(origins="*", maxAge=3600) @RestController @RequestMapping("/api/bookings")
public class BookingController { @Autowired BookingRepository repo; @Autowired PackageRepository packageRepo;
@PostMapping("/kodisha/{packageId}") public ResponseEntity<?> kodisha(@PathVariable Long packageId, @RequestParam(defaultValue="1") Integer miezi, Authentication a){ PackageKukodisha p=packageRepo.findById(packageId).orElse(null); if(p==null) return ResponseEntity.notFound().build(); Booking b=new Booking(); b.setUsername(a.getName()); b.setPackageId(p.getId()); b.setJinaPackage(p.getJinaPackage()); b.setAina(p.getAina()); b.setBei(p.getBei()*miezi); b.setMiezi(miezi); b.setTareheKuanza(LocalDateTime.now()); b.setTareheMwisho(LocalDateTime.now().plusMonths(miezi)); b.setImelipa(false); b.setStatus("ACTIVE"); b.setSikuZilizobaki(miezi*30); return ResponseEntity.ok(repo.save(b)); }
@PostMapping("/{id}/lipa") public ResponseEntity<?> lipa(@PathVariable Long id, @RequestParam String njia, @RequestParam String muamala){ return repo.findById(id).map(b->{ b.setImelipa(true); b.setNjiaMalipo(njia); b.setNambaMuamala(muamala); b.setStatus("ACTIVE"); if(b.getTareheMwisho().isBefore(LocalDateTime.now())) b.setTareheMwisho(LocalDateTime.now().plusMonths(b.getMiezi())); return ResponseEntity.ok(repo.save(b)); }).orElse(ResponseEntity.notFound().build()); }
@GetMapping("/yangu/status") public ResponseEntity<?> status(Authentication a){ List<Booking> z=repo.findByUsername(a.getName()); for(Booking b:z){ if("LOCKED".equals(b.getStatus())) return ResponseEntity.status(403).body("LOCKED: Lipa "+b.getBei()+" TZS kwa "+b.getJinaPackage()); } return ResponseEntity.ok(z); }
@GetMapping("/yangu") public List<Booking> yangu(Authentication a){ return repo.findByUsername(a.getName()); }
}
